	token, _ := url.QueryUnescape(m[1])
	if r := e.Do("POST", "/v1/invites", e.Acme.Key, map[string]string{"email": "owner@acme.example", "role": "member"}); r.Code != http.StatusConflict {
		t.Fatalf("invite a member: %s", r)
